    for r in range(H):
        if len(set(inp[r]))==1 and inp[r][0]!=bg: lrc=inp[r][0]; break
    sr=[r for r in range(H) if all(v==lrc for v in inp[r])]
    sc=[c for c in range(W) if all(inp[r][c]==lrc for r in range(H))]
    pts_r=[-1]+sorted(sr)+[H]; pts_c=[-1]+sorted(sc)+[W]
    rb=[(pts_r[i],pts_r[i+1]) for i in range(len(pts_r)-1)]
    cb=[(pts_c[j],pts_c[j+1]) for j in range(len(pts_c)-1)]
    cands=[]
    for r0,r1 in rb:
        for c0,c1 in cb:
            patcells=[(dr,dc,inp[r0+dr][c0+dc]) for dr in range(r1-r0) for dc in range(c1-c0)
                      if inp[r0+dr][c0+dc] not in (bg,lrc)]
            if patcells:
                cands.append({'r0':r0,'c0':c0,'ncells':len(patcells),'offs':[(p[0],p[1],p[2]) for p in patcells]})
    best=max(cands,key=lambda x:x['ncells'])
    off=best['offs']
    out=[[bg]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if i in sr or j in sc: out[i][j]=lrc
