            if best is None or pts>best[0]: best=(pts,rbb[0],cbb[0])
    r0,c0=best[1],best[2]
    h=max(r for r in range(H) for c in range(W) if inp[r][c] not in (bg,lc))/0.5 if False else 0
    # find extent of the chosen block's non-bg cells
    rr=[r for r in range(H) for c in range(W) if inp[r][c] not in (bg,lc)]
    cols=[c for r in rr for c in range(W) if r==rr[0]] if False else []
    # better: use bbox of non-(bg,lc) cells within candidate band only... instead compute from whole grid then clamp
    Rrs=[r for r in range(H) for c in range(W) if inp[r][c] not in (bg,lc)]
    Ccs=[c for r in range(H) for c in range(W) if inp[r][c] not in (bg,lc)]
    rmin,rmax=min(Rrs),max(Rrs); cmin,cmax=min(Ccs),max(Ccs)
    h=rmax-rmin+1; w=cmax-cmin+1
    src=[[inp[r0+i][c0+j] for j in range(w)] for i in range(h)]
    o=[[bg]*W for _ in range(H)]
    for r in sr:
        for c in range(W): o[r][c]=lc
    for c in sc:
        for r in range(H): o[r][c]=lc
    for rbb in rb:
        for cbb in cb:
            ro,co=rbb[0],cbb[0]
            ni=min(h,rbb[1]-ro); nj=min(w,cbb[1]-co)
            for a in range(ni):
                for b in range(nj):
                    o[ro+a][co+b]=src[a][b]
    return o

