import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); g1,g1o=G['Demo pair 1 input'],G['Demo pair 1 output']; g2,g2o=G['Demo pair 2 input'],G['Demo pair 2 output']; ti=G['Test input']

def solve(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(v for row in inp for v in row); bg=cnt.most_common(1)[0][0]
    lc=None
    for c in cnt:
        if c!=bg and (any(all(v==c for v in inp[r]) for r in range(H)) or any(all(inp[r][cc]==c for r in range(H)) for cc in range(W))): lc=c; break
    sr=set(r for r in range(H) if all(v==lc for v in inp[r]))
    sc=set(c for c in range(W) if all(inp[r][c]==lc for r in range(H)))
    def make(seps,n):
        res=[]; prev=0
        for s in sorted(seps+[n]):
            if s>prev: res.append((prev,min(s,n))); prev=s+1
        return res
    rb=make(sorted(sr),H); cb=make(sorted(sc),W)
    # template band = band containing the most non-(bg,lc) cells
    best=None
    for rbb in rb:
        for cbb in cb:
            pts=sum(1 for r in range(rbb[0],rbb[1]) for c in range(cbb[0],cbb[1]) if inp[r][c]!=bg and inp[r][c]!=lc)
            if best is None or pts>best[0]: best=(pts,rbb[0],cbb[0],rbb[1],cbb[1])
    _,r0,c0,r1,c1=best
    h=r1-r0; w=c1-c0
    src=[[inp[r0+i][c0+j] for j in range(w)] for i in range(h)]
    o=[[bg]*W for _ in range(H)]
    for r in sr:
        for c in range(W): o[r][c]=lc
    for c in sc:
        for r in range(H): o[r][c]=lc
    for rbb in rb:
        for cbb in cb:
            ro,co=rbb[0],cbb[0]
            for a in range(min(h,rbb[1]-ro)):
                for b in range(min(w,cbb[1]-co)):
                    o[ro+a][co+b]=src[a][b]
    return o

print('d1:',solve(g1)==g1o,'d2:',solve(g2)==g2o)
